#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

/**
 * Problem: 2015-01 - Missing Numbers
 * 
 * 解題思路：
 * 1. 題目給出 M 個列表，第 i 個列表比第 i-1 個列表少一個數字。
 * 2. 任務是找出每一對相鄰列表之間缺失的那一個數字。
 * 3. 由於每一對列表只差一個數字，最簡單且有效的方法是計算兩個列表的總和。
 * 4. 缺失的數字 = (第 i 個列表的總和) - (第 i+1 個列表的總和)。
 * 5. 注意資料範圍：M*N <= 5,000,000，且數字 < 65,536。使用 long long 儲存總和以防溢位。
 */

int main() {
    int m;
    long long n;
    while (cin >> m >> n) {
        vector<long long> current_list(n);
        long long current_sum = 0;
        for (int i = 0; i < n; ++i) {
            cin >> current_list[i];
            current_sum += current_list[i];
        }

        for (int i = 1; i < m; ++i) {
            long long next_sum = 0;
            long long val;
            for (int j = 0; j < n - i; ++j) {
                cin >> val;
                next_sum += val;
            }
            cout << current_sum - next_sum << endl;
            current_sum = next_sum;
        }
    }
    return 0;
}
